        var s2 = pkg.ray.get(2);
        assertClose("ray.2.2.2.p.x", 28.013628702339357d, s2.p.x, 1.0e-6);
        assertClose("ray.2.2.2.p.y", -6.940821781272575d, s2.p.y, 1.0e-6);
